2657	        &self,
2658	        guest: &mut G,
2659	        call: StatFamily,
2660	    ) -> Result<i64, Error> {
2661	        if guest.config().virtualize_metadata {
2662	            // NB: let kernel handle error codes, it's not easy to do so without
2663	            // kernel because there're many corner cases. i.e.: even access
2664	            // filepath from tracer may cause tracer to hang under certain fuse
2665	            // filesystem (squashfs_ll).
2666	            guest.inject(Syscall::from(call)).await?;
2667	            let statptr = call.stat().ok_or(Errno::EFAULT)?;
2668	            let inode_override = match call {
2669	                StatFamily::Fstat(call) => guest
2670	                    .thread_state()
2671	                    .with_detfd(call.fd(), |detfd| {
2672	                        deterministic_stdio_inode_for_resource(call.fd(), detfd.resource())
2673	                    })
2674	                    .ok()
2675	                    .flatten(),
2676	                _ => None,
2677	            };
2678	            let mut memory = guest.memory();
2679	            let stat = memory.read_value(statptr.0)?;
2680	            let stat = self.determinize_stat(guest, stat, inode_override).await?;
2681	            memory.write_value(statptr.0, &stat.into())?;
2682	            Ok(0)
2683	        } else {
2684	            Ok(self.record_or_replay(guest, call).await?)
2685	        }
2686	    }
