166	/// Recognize only a complete kernel pipe/socket symlink target.
167	fn anonymous_proc_fd_identity(target: &[u8]) -> Option<AnonymousProcFdIdentity> {
168	    for (kind, prefix) in [
169	        ("pipe", b"pipe:[".as_slice()),
170	        ("socket", b"socket:[".as_slice()),
171	    ] {
172	        let Some(digits) = target
173	            .strip_prefix(prefix)
174	            .and_then(|rest| rest.strip_suffix(b"]"))
175	        else {
176	            continue;
177	        };
178	        if digits.is_empty() || !digits.iter().all(u8::is_ascii_digit) {
179	            continue;
180	        }
181	        let raw_inode = std::str::from_utf8(digits).ok()?.parse().ok()?;
182	        return Some(AnonymousProcFdIdentity { kind, raw_inode });
183	    }
184	    None
185	}
