187	/// Match a raw identity against cached current-process inherited-stdio identities.
188	/// Callers exclude ordinary replacement objects before filling this array.
189	///
190	/// Iterating in fd order deliberately matches the last-insert-wins behavior of
191	/// the maps sanitizer's `stdio_by_raw_inode` table when stdio descriptors alias.
192	fn deterministic_stdio_inode_for_raw(
193	    raw_inode: RawInode,
194	    stdio_raw_inodes: &[Option<RawInode>; 3],
195	) -> Option<DetInode> {
196	    let mut matched = None;
197	    for (fd, cached) in stdio_raw_inodes.iter().enumerate() {
198	        if *cached == Some(raw_inode) {
199	            matched = deterministic_stdio_inode(fd as i32);
200	        }
201	    }
202	    matched
203	}
