268	    /// Drop provenance for a Hermit mount hidden by an explicit user mount.
269	    /// The hidden mount must also be omitted from the mount plan: otherwise its
270	    /// private root would remain visible as a lower stacked mountinfo row even
271	    /// though no pathname could reopen that exact layer afterward.
272	    pub(super) fn discard_mounts_shadowed_by(
273	        &mut self,
274	        mounts: &mut Vec<Mount>,
275	        overriding_target: &Path,
276	    ) {
277	        // Host canonicalization describes the namespace only until the first
278	        // user mount that can replace an ancestor of this target. After that,
279	        // pathname resolution must follow the ordered mount plan rather than
280	        // the launcher's host tree. For example, mounting a new `/var` changes
281	        // what a later `/var/run/nscd` names and must not remove the earlier
282	        // hardening mount installed at the host-resolved `/run/nscd`.
283	        let resolution_changed = self
284	            .user_mount_targets
285	            .iter()
286	            .any(|earlier| overriding_target.starts_with(earlier));
287	        let resolved_override = if resolution_changed {
288	            overriding_target.to_path_buf()
289	        } else {
290	            canonical_mount_target(overriding_target)
291	        };
292	        mounts.retain(|mount| {
293	            !canonical_mount_target(mount.get_target()).starts_with(&resolved_override)
294	        });
295	        self.mountinfo_roots.retain(|source| {
296	            !canonical_mount_target(&source.target).starts_with(&resolved_override)
297	        });
298	        self.user_mount_targets
299	            .push(overriding_target.to_path_buf());
300	    }
