340	/// synthetic overflow group (`nobody:x:65534`) when the host lacks one. Binding
341	/// this frozen copy read-only over `/etc/group` keeps guest group-name
342	/// resolution stable across otherwise-identical runs.
343	fn frozen_group_file() -> Result<tempfile::NamedTempFile, Error> {
344	    let mut contents = fs::read_to_string(GROUP_FILE)
345	        .context("Failed to read the host group database for the guest")?;
346	    let has_overflow_group = contents.lines().any(|line| {
347	        line.split(':')
348	            .nth(2)
349	            .is_some_and(|gid| gid == OVERFLOW_GID)
350	    });
351	    if !has_overflow_group {
352	        if !contents.ends_with('\n') {
353	            contents.push('\n');
354	        }
355	        contents.push_str("nobody:x:");
356	        contents.push_str(OVERFLOW_GID);
357	        contents.push_str(":\n");
358	    }
359	
360	    let mut group_file = tempfile::NamedTempFile::new()
361	        .context("Failed to create the frozen group database for the guest")?;
362	    group_file
363	        .write_all(contents.as_bytes())
364	        .context("Failed to populate the frozen group database for the guest")?;
365	    group_file
366	        .as_file()
367	        .set_permissions(fs::Permissions::from_mode(0o644))
368	        .context("Failed to set permissions on the frozen guest group database")?;
369	    Ok(group_file)
370	}
