1900	/// be tidy. `fs::canonicalize` runs after the container's mounts are applied, and
1901	/// the container bind-mounts a fresh empty tmpfs over `/tmp`
1902	/// (`bin/hermit/container.rs`). So a cwd beneath `/tmp` is genuinely absent from
1903	/// the guest's mount namespace and `canonicalize` returns a perfectly correct
1904	/// `NotFound` -- for a directory the user can `ls`.
1905	///
1906	/// Reported 2026-08-25 as "run_kvm_ cli tests fail from a git worktree". They do
1907	/// not. Measured across five working directories with one binary: a PLAIN
1908	/// directory under `/tmp` with no git in it FAILS, and a linked git worktree
1909	/// under `/home` WORKS. The only property that tracks the failure is "the cwd is
1910	/// under /tmp"; `/tmp` itself resolves because the mount POINT exists. The git
1911	/// hypothesis cost real investigation time, and it came from this message saying
1912	/// only "No such file or directory".
1913	///
1914	/// It mattered more than a stray report because the historical landing recipe
1915	/// placed detached worktrees below `/tmp`, exactly where this fires. Current
1916	/// dev-hermit worktrees are created through wrkslots below `worktrees/`, but the
1917	/// diagnostic remains necessary for arbitrary callers and older checkouts.
1918	///
1919	/// The message names the mechanism and both ways out. It deliberately does NOT
1920	/// silently fall back to `/`: changing the guest's working directory out from
1921	/// under a caller who asked for a specific one would trade a loud, correct
1922	/// failure for a quiet, wrong success.
1923	fn kvm_cwd_resolution_error(requested_cwd: &Path, error: &std::io::Error) -> Error {
1924	    let under_replaced_tmp = requested_cwd.starts_with(CONTAINER_REPLACED_TMP)
1925	        && requested_cwd != Path::new(CONTAINER_REPLACED_TMP);
1926	    if error.kind() == std::io::ErrorKind::NotFound && under_replaced_tmp {
1927	        anyhow!(
1928	            "failed to resolve KVM guest working directory {:?}: {error}\n\
1929	             \n\
1930	             This directory may well exist on the host. The container replaces \
1931	             {CONTAINER_REPLACED_TMP} with a private, empty tmpfs, so nothing beneath \
1932	             {CONTAINER_REPLACED_TMP} is visible to the guest, and resolving the working \
1933	             directory happens inside that mount namespace.\n\
1934	             Either run from a directory outside {CONTAINER_REPLACED_TMP}, or pass \
1935	             --workdir with a path that exists inside the guest.",
1936	            requested_cwd
1937	        )
1938	    } else {
1939	        anyhow!(
1940	            "failed to resolve KVM guest working directory {:?}: {error}",
1941	            requested_cwd
1942	        )
1943	    }
