1952	/// KVM does not permit guest namespace changes. Later guest-visible mountinfo
1953	/// views still use Detcore's existing ordered-subset validation.
1954	fn prepare_kvm_mountinfo_config(
1955	    config: &mut DetConfig,
1956	    capture: impl FnOnce() -> Result<Vec<u64>, Error>,
1957	) -> Result<(), Error> {
1958	    if !config.mountinfo_mount_ids_captured
1959	        && (!config.mountinfo_mount_ids.is_empty() || !config.fdinfo_unlisted_mount_ids.is_empty())
1960	    {
1961	        anyhow::bail!("KVM mount identities have no producer-captured namespace");
1962	    }
1963	    let order = capture().context("failed to capture the KVM backend mount namespace")?;
1964	    if config.mountinfo_mount_ids_captured {
1965	        if config.mountinfo_mount_ids != order {
1966	            anyhow::bail!(
1967	                "KVM producer-captured mount identities do not match the backend namespace"
1968	            );
1969	        }
1970	    } else {
1971	        config.mountinfo_mount_ids = order;
1972	        config.mountinfo_mount_ids_captured = true;
1973	    }
1974	    // The backend now exposes the actual namespace's devices. There is no
1975	    // synthetic 0:1 root device to translate; stat and mountinfo use the same
1976	    // raw identities before entering Detcore's shared DevicePool.
1977	    config.mountinfo_device_rewrites.clear();
1978	    Ok(())
