56	fn parse_mountinfo_row(line: &[u8]) -> Option<MountInfoRow> {
57	    let fields = line.split(|byte| *byte == b' ').collect::<Vec<_>>();
58	    if fields.iter().any(|field| field.is_empty()) {
59	        return None;
60	    }
61	    let separator = fields.iter().position(|field| *field == b"-")?;
62	    if separator < 6 || separator + 4 != fields.len() {
63	        return None;
64	    }
65	    let mut device = fields[2].split(|byte| *byte == b':');
66	    let major = u32::try_from(decimal(device.next()?)?).ok()?;
67	    let minor = u32::try_from(decimal(device.next()?)?).ok()?;
68	    if device.next().is_some() {
69	        return None;
70	    }
71	    let mut raw_peer_groups = Vec::new();
72	    for field in &fields[6..separator] {
73	        if let Some(raw) = mount_peer_group(field)? {
74	            raw_peer_groups.push(raw);
75	        } else if field
76	            .iter()
77	            .position(|byte| *byte == b':')
78	            .is_some_and(|separator| decimal(&field[separator + 1..]).is_some())
79	        {
80	            // Unknown numeric optional fields can carry mount-namespace
81	            // identity just like the peer-group fields above. Passing one
82	            // through would expose an unsanitized host identifier, so refuse
83	            // until its Linux semantics and deterministic mapping are known.
84	            return None;
85	        }
86	    }
87	    Some(MountInfoRow {
88	        raw_mount_id: decimal(fields[0])?,
89	        raw_parent_id: decimal(fields[1])?,
90	        raw_device: libc::makedev(major, minor),
91	        root: fields[3].to_vec(),
92	        raw_peer_groups,
93	    })
94	}
