97	///
98	/// Empty files are valid empty snapshots. Malformed rows and duplicate mount
99	/// IDs are rejected so every producer and consumer accepts the same grammar.
100	pub fn parse_mountinfo(contents: &[u8]) -> Option<Vec<MountInfoRow>> {
101	    if contents.is_empty() {
102	        return Some(Vec::new());
103	    }
104	    let body = contents.strip_suffix(b"\n").unwrap_or(contents);
105	    if body.is_empty() {
106	        return None;
107	    }
108	    let rows = body
109	        .split(|byte| *byte == b'\n')
110	        .map(parse_mountinfo_row)
111	        .collect::<Option<Vec<_>>>()?;
112	    let mut seen = BTreeSet::new();
113	    rows.iter()
114	        .all(|row| seen.insert(row.raw_mount_id))
115	        .then_some(rows)
116	}
