169	    // Allocate the next deterministic inode.  This takes the raw-inode and
170	    // can return an existing mapping or extend the mapping by creating a
171	    // new deterministic inode. The returned inode is strictly increasing
172	    // to avoid inode re-use issue in some filesystem like ext4.
173	    fn add_inode(&mut self, raw_inode: RawInode, mtime: LogicalTime) -> (DetInode, LogicalTime) {
174	        match self.inodes.get(&raw_inode) {
175	            None => {
176	                // THE determinization boundary: the single place a host inode
177	                // is deliberately mapped to a deterministic one. The value is
178	                // minted from a monotonic counter, never derived from the host
179	                // inode's bits.
180	                let new = DetInode::mint(self.next_inode);
181	                self.next_inode += 1;
182	                assert!(self.inodes.insert(raw_inode, new).is_none());
183	                let prev = self.detinodes_info.insert(
184	                    new,
185	                    DetInodeInfo {
186	                        raw: raw_inode,
187	                        mtime,
188	                    },
189	                );
190	                assert!(prev.is_none()); // Should not have been previously used.
191	                (new, mtime)
192	            }
193	            Some(dino) => {
194	                let info = self
195	                    .detinodes_info
196	                    .get(dino)
197	                    .expect("Internal invariant broken, det_ino missing entry");
198	                (*dino, info.mtime)
199	            }

