28	    fn traverse(
29	        &mut self,
30	        offset: u64,
31	        observe: &mut impl FnMut() -> Result<Vec<u8>, i64>,
32	    ) -> Result<(), i64> {
33	        self.reset();
34	        if offset != 0 {
35	            self.buffer = observe()?;
36	            self.from = offset.min(self.buffer.len() as u64) as usize;
37	            self.end = true;
38	        }
39	        Ok(())
40	    }
41	
42	    pub(crate) fn read(
43	        &mut self,
44	        positioned_offset: Option<u64>,
45	        count: usize,
46	        mut observe: impl FnMut() -> Result<Vec<u8>, i64>,
47	        mut copy: impl FnMut(&[u8]) -> Result<usize, i64>,
48	    ) -> i64 {
49	        let offset = positioned_offset.unwrap_or(self.file_pos);
50	        if offset > i64::MAX as u64 {
51	            return -i64::from(libc::EINVAL);
52	        }
53	        if count == 0 {
54	            return 0;
55	        }
56	        if offset == 0 {
57	            self.reset();
58	        }
59	        if offset != self.read_pos {
60	            if let Err(error) = self.traverse(offset, &mut observe) {
61	                self.read_pos = 0;
62	                self.reset();
63	                return error;
64	            }
65	            self.read_pos = offset;
66	        }
67	        if self.from == self.buffer.len() && !self.end {
68	            match observe() {
69	                Ok(bytes) => self.buffer = bytes,
70	                Err(error) => return error,
71	            }
72	            self.from = 0;
73	            self.end = true;
74	        }
75	        let available = (self.buffer.len() - self.from).min(count);
76	        if available == 0 {
77	            return 0;
78	        }
79	        let copied = match copy(&self.buffer[self.from..self.from + available]) {
80	            Ok(0) => return -i64::from(libc::EFAULT),
81	            Ok(copied) => copied,
82	            Err(error) => return error,
83	        };
84	        assert!(
85	            copied <= available,
86	            "fdinfo copy exceeded the offered bytes"
87	        );
88	        self.from += copied;
89	        self.read_pos += copied as u64;
90	        if positioned_offset.is_none() {
91	            self.file_pos = self.read_pos;
92	        }
93	        copied as i64
94	    }
95	
96	    pub(crate) fn seek(
97	        &mut self,
98	        offset: i64,
99	        whence: libc::c_int,
100	        mut observe: impl FnMut() -> Result<Vec<u8>, i64>,
101	    ) -> i64 {
102	        let offset = match whence {
103	            libc::SEEK_SET => Some(offset),
104	            libc::SEEK_CUR => (self.file_pos as i64).checked_add(offset),
105	            _ => None,
106	        };
107	        let Some(offset) = offset.filter(|offset| *offset >= 0) else {
108	            return -i64::from(libc::EINVAL);
109	        };
110	        if offset as u64 != self.read_pos {
111	            if let Err(error) = self.traverse(offset as u64, &mut observe) {
112	                self.file_pos = 0;
113	                self.read_pos = 0;
114	                self.reset();
115	                return error;
116	            }
117	            self.read_pos = offset as u64;
118	        }
119	        self.file_pos = offset as u64;
120	        offset
121	    }
122	}
